        return DataStatistics._round2(total / len(data))

    def median(self, data):
        if not data:
            raise ValueError("Data vector is empty.")
        data = sorted(data)
        n = len(data)
        if n % 2 == 0:
            return DataStatistics._round2((data[n // 2 - 1] + data[n // 2]) / 2)
        else:
            return data[n // 2]

    def mode(self, data):
        if not data:
