        self.arguments = {}    # std::map<std::string, std::string>
        self.required = set()  # std::set<std::string>
        self.types = {}        # std::map<std::string, std::string>
        self.type_converters = {}  # std::map<std::string, std::function<...>>
        self.initialize_converters()

