        users.get(sender).add(messageInfo);
        users.get(receiver).add(messageInfo);
        return true;
    }

    public List<Message> getMessages(String username) {
        if (!users.containsKey(username)) {
            return new ArrayList<>();
        }
        return users.get(username);
