import sqlite3
import traceback


class MovieTicketDB:
    class Ticket:
        def __init__(self, id, movie_name, theater_name, seat_number, customer_name):
            self.id = id
            self.movie_name = movie_name
            self.theater_name = theater_name
            self.seat_number = seat_number
            self.customer_name = customer_name

