                .map(x -> x - mean)
                .collect(Collectors.toList());

        double fourthMoment = centeredData.stream()
                .mapToDouble(x -> Math.pow(x, 4))
                .average().orElse(0);

        double kurtosisValue = (fourthMoment / Math.pow(stdDev, 4)) - 3;

        return kurtosisValue;
    }

