    if (s == "inf")  return "Infinity";
    if (s == "-inf") return "-Infinity";
    if (s == "nan" || s == "-nan") return "NaN";

    // Java always shows a fractional part in plain notation ("2.0", not "2").
    if (s.find_first_of(".e") == std::string::npos) {
        s += ".0";
    }
    return s;
}

