            createTable();
        } else {
            std::cerr << "java.sql.SQLException: "
                      << sqlite3_errmsg(connection) << std::endl;
            sqlite3_close(connection);
            connection = nullptr;
        }
    }

    MovieTicketDB(const MovieTicketDB&) = delete;
    MovieTicketDB& operator=(const MovieTicketDB&) = delete;

    ~MovieTicketDB() { close(); }

