            this.perPage = perPage;
            this.totalPages = totalPages;
            this.totalItems = totalItems;
            this.hasPrevious = hasPrevious;
            this.hasNext = hasNext;
            this.data = data != null ? new ArrayList<>(data) : new ArrayList<>();
