        sqlite3_bind_text(pstmt, 1, username.c_str(), -1, SQLITE_TRANSIENT);
        if (sqlite3_step(pstmt) != SQLITE_DONE) {
            printStackTrace(sqlite3_errmsg(connection));
        }
        sqlite3_finalize(pstmt);
