static std::string xmlUnescape(const std::string& s) {
    std::string out; out.reserve(s.size());
    for (size_t i = 0; i < s.size(); ) {
        if (s[i] == '&') {
            size_t sc = s.find(';', i);
            if (sc != std::string::npos && sc - i <= 10) {
                std::string ent = s.substr(i+1, sc-i-1);
                if (ent == "amp") out += '&';
                else if (ent == "lt") out += '<';
                else if (ent == "gt") out += '>';
                else if (ent == "quot") out += '"';
                else if (ent == "apos") out += '\'';
                else if (!ent.empty() && ent[0] == '#') {
                    long code = 0;
                    try {
                        if (ent.size() > 1 && (ent[1]=='x'||ent[1]=='X')) code = std::stol(ent.substr(2), nullptr, 16);
                        else code = std::stol(ent.substr(1));
                    } catch (...) { code = -1; }
                    if (code > 0) {
                        // encode as UTF-8
                        if (code < 0x80) out += (char)code;
                        else if (code < 0x800) { out += (char)(0xC0|(code>>6)); out += (char)(0x80|(code&0x3F)); }
                        else { out += (char)(0xE0|(code>>12)); out += (char)(0x80|((code>>6)&0x3F)); out += (char)(0x80|(code&0x3F)); }
                    }
                    i = sc + 1; continue;
                } else { out += s[i]; i++; continue; }
                i = sc + 1; continue;
            }
        }
        out += s[i]; i++;
    }
    return out;
}
