    while (true) {
        size_t t1 = s.find("<t", pos);
        if (t1 == std::string::npos) break;
        size_t gt = s.find('>', t1);
        if (gt == std::string::npos) break;
        if (s[gt - 1] == '/') { pos = gt + 1; continue; }  // <t/>
        size_t end = s.find("</t>", gt);
        if (end == std::string::npos) break;
        out += xmlUnescape(s.substr(gt + 1, end - gt - 1));
        pos = end + 4;
    }
