        if (s[i] != '&') { out += s[i]; continue; }
        size_t sc = s.find(';', i);
        if (sc == std::string::npos || sc - i > 10) { out += s[i]; continue; }
        std::string ent = s.substr(i + 1, sc - i - 1);
