#include <chrono>
#include <cstdint>
#include <cstdio>
#include <ctime>
#include <stdexcept>
#include <string>

class TimeUtils {
public:
    using LocalDateTime = std::chrono::time_point<std::chrono::system_clock, std::chrono::seconds>;

    TimeUtils() : datetime(nowLocal()) {}

    std::string getCurrentTime() {
        return format(datetime, "%H:%M:%S");
    }

    std::string getCurrentDate() {
        return format(datetime, "%Y-%m-%d");
    }

    std::string addSeconds(int seconds) {
        LocalDateTime newDatetime = datetime + std::chrono::seconds(seconds);
        return format(newDatetime, "%H:%M:%S");
    }

    LocalDateTime stringToDatetime(const std::string& str) {
        int y, mo, d, h, mi, s;
        if (std::sscanf(str.c_str(), "%d-%d-%d %d:%d:%d", &y, &mo, &d, &h, &mi, &s) != 6) {
            throw std::runtime_error("DateTimeParseException");
        }
        return of(y, mo, d, h, mi, s);
    }

    std::string datetimeToString(const LocalDateTime& dt) {
        return format(dt, "%Y-%m-%d %H:%M:%S");
    }

    int getMinutes(const std::string& stringTime1, const std::string& stringTime2) {
        LocalDateTime time1 = stringToDatetime(stringTime1);
        LocalDateTime time2 = stringToDatetime(stringTime2);
        long long minutes = std::chrono::duration_cast<std::chrono::minutes>(time2 - time1).count();
        if (minutes > INT32_MAX || minutes < INT32_MIN) {
            throw std::runtime_error("ArithmeticException: integer overflow");
        }
        return static_cast<int>(minutes);
    }

    std::string getFormatTime(int year, int month, int day, int hour, int minute, int second) {
        return format(of(year, month, day, hour, minute, second), "%Y-%m-%d %H:%M:%S");
    }

private:
    LocalDateTime datetime;

    static void validateTime(int hour, int minute, int second) {
        if (hour < 0 || hour > 23 || minute < 0 || minute > 59 || second < 0 || second > 59)
            throw std::runtime_error("DateTimeException: invalid time");
    }

    static LocalDateTime of(int y, int mo, int d, int h, int mi, int s) {
        using namespace std::chrono;
        validateTime(h, mi, s);
        year_month_day ymd(year{y}, month{static_cast<unsigned>(mo)}, day{static_cast<unsigned>(d)});
        if (!ymd.ok()) throw std::runtime_error("DateTimeException: invalid date");
        return sys_days(ymd) + hours(h) + minutes(mi) + seconds(s);
    }

    static LocalDateTime nowLocal() {
        std::time_t now = std::time(nullptr);
        std::tm lt{};
#ifdef _WIN32
        localtime_s(&lt, &now);
#else
        localtime_r(&now, &lt);
#endif
        return of(lt.tm_year + 1900, lt.tm_mon + 1, lt.tm_mday, lt.tm_hour, lt.tm_min, lt.tm_sec);
    }

    static std::tm toTm(const LocalDateTime& tp) {
        std::time_t tt = static_cast<std::time_t>(tp.time_since_epoch().count());
        std::tm tmv{};
#ifdef _WIN32
        gmtime_s(&tmv, &tt);
#else
        gmtime_r(&tt, &tmv);
#endif
        return tmv;
    }

    static std::string format(const LocalDateTime& tp, const char* fmt) {
        std::tm tmv = toTm(tp);
        char buf[64];
        std::size_t n = std::strftime(buf, sizeof buf, fmt, &tmv);
        return std::string(buf, n);
    }
};
