The task: translate Python sqlite3-based BookManagementDB to C++. Must preserve behavior: create table if not exists, add/remove/borrow/return/search books. C++ doesn't have sqlite3 built-in, but idiomatic approach is using sqlite3 C API. I'll write a class with sqlite3* connection, sqlite3_stmt usage, parameter binding, commit (autocommit by default in sqlite3 C API since Python's sqlite3 default isolation_level actually commits via explicit commit; in C each statement executes and commits automatically unless within transaction — behavior equivalent).

search_books returns list of tuples (id, title, author, available). In C++, return std::vector<std::tuple<int, std::string, std::string, int>> or a struct. Keep tuple to mirror.

Include destructor closing db. Handle db_name as std::string.

Write compact code:

```cpp
#include <sqlite3.h>
#include <string>
#include <vector>
#include <tuple>
#include <stdexcept>

class BookManagementDB {
public:
    explicit BookManagementDB(const std::string& db_name) {
        if (sqlite3_open(db_name.c_str(), &connection) != SQLITE_OK) {
            std::string err = sqlite3_errmsg(connection);
            sqlite3_close(connection);
            connection = nullptr;
            throw std::runtime_error("unable to open database: " + err);
        }
        create_table();
    }

    ~BookManagementDB() {
        if (connection) sqlite3_close(connection);
    }

    BookManagementDB(const BookManagementDB&) = delete;
    BookManagementDB& operator=(const BookManagementDB&) = delete;

    void create_table() {
        exec("CREATE TABLE IF NOT EXISTS books ("
             "id INTEGER PRIMARY KEY,"
             "title TEXT,"
             "author TEXT,"
             "available INTEGER)");
    }

    void add_book(const std::string& title, const std::string& author) {
        sqlite3_stmt* stmt = nullptr;
        if (sqlite3_prepare_v2(connection,
                "INSERT INTO books (title, author, available) VALUES (?, ?, 1)",
                -1, &stmt, nullptr) != SQLITE_OK)
            throw std::runtime_error(sqlite3_errmsg(connection));
        sqlite3_bind_text(stmt, 1, title.c_str(), -1, SQLITE_TRANSIENT);
        sqlite3_bind_text(stmt, 2, author.c_str(), -1, SQLITE_TRANSIENT);
        if (sqlite3_step(stmt) != SQLITE_DONE) {
            sqlite3_finalize(stmt);
            throw std::runtime_error(sqlite3_errmsg(connection));
        }
        sqlite3_finalize(stmt);
    }

    void remove_book(int book_id) { execute_id("DELETE FROM books WHERE id = ?", book_id); }
    void borrow_book(int book_id) { execute_id("UPDATE books SET available = 0 WHERE id = ?", book_id); }
    void return_book(int book_id) { execute_id("UPDATE books SET available = 1 WHERE id = ?", book_id); }

    std::vector<std::tuple<int, std::string, std::string, int>> search_books() {
        std::vector<std::tuple<int, std::string, std::string, int>> books;
        sqlite3_stmt* stmt = nullptr;
        if (sqlite3_prepare_v2(connection, "SELECT * FROM books", -1, &stmt, nullptr) != SQLITE_OK)
            throw std::runtime_error(sqlite3_errmsg(connection));
        while (sqlite3_step(stmt) == SQLITE_ROW) {
            int id = sqlite3_column_int(stmt, 0);
            const unsigned char* t = sqlite3_column_text(stmt, 1);
            const unsigned char* a = sqlite3_column_text(stmt, 2);
            int avail = sqlite3_column_int(stmt, 3);
            books.emplace_back(id,
                t ? reinterpret_cast<const char*>(t) : "",
                a ? reinterpret_cast<const char*>(a) : "",
                avail);
        }
        sqlite3_finalize(stmt);
        return books;
    }

private:
    sqlite3* connection = nullptr;

    void exec(const char* sql) {
        char* err = nullptr;
        if (sqlite3_exec(connection, sql, nullptr, nullptr, &err) != SQLITE_OK) {
            std::string msg = err ? err : "unknown error";
            sqlite3_free(err);
            throw std::runtime_error(msg);
        }
    }

    void execute_id(const char* sql, int book_id) {
        sqlite3_stmt* stmt = nullptr;
        if (sqlite3_prepare_v2(connection, sql, -1, &stmt, nullptr) != SQLITE_OK)
            throw std::runtime_error(sqlite3_errmsg(connection));
        sqlite3_bind_int(stmt, 1, book_id);
        if (sqlite3_step(stmt) != SQLITE_DONE) {
            sqlite3_finalize(stmt);
            throw std::runtime_error(sqlite3_errmsg(connection));
        }
        sqlite3_finalize(stmt);
    }
};
```

