                rows.push_back(row); row.clear();
            } else {
                field += c; ++i;
            }
        }
        if (!field.empty() || !row.empty()) {
            row.push_back(field);
            rows.push_back(row);
        }
        return rows;
    }

    static std::string quote_field(const std::string& s) {
        bool needs = s.find_first_of(",\"\r\n") != std::string::npos;
        if (!needs) return s;
