        for (auto it = cookies->begin(); it != cookies->end(); ++it) {
            if (!first) joined += "; ";
            first = false;
            std::string value_str =
                it.value().is_string() ? it.value().get<std::string>() : it.value().dump();
            joined += it.key() + "=" + value_str;
        }
        request["cookies"] = joined;
    }
};
