#include <cstdlib>
#include <random>
#include <set>
#include <stack>
#include <utility>
#include <vector>
#include <string>

class MahjongConnect {
public:
    std::vector<int> BOARD_SIZE;
    std::vector<std::string> ICONS;
    std::vector<std::vector<std::string>> board;

    MahjongConnect(const std::vector<int>& board_size, const std::vector<std::string>& icons)
        : BOARD_SIZE(board_size), ICONS(icons), board(create_board()) {}

    std::vector<std::vector<std::string>> create_board() {
        std::vector<std::vector<std::string>> b(
            BOARD_SIZE[0], std::vector<std::string>(BOARD_SIZE[1]));
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<std::size_t> dist(0, ICONS.size() - 1);
        for (auto& row : b)
            for (auto& cell : row)
                cell = ICONS[dist(gen)];
        return b;
    }

    bool is_valid_move(std::pair<int,int> pos1, std::pair<int,int> pos2) {
        int x1 = pos1.first, y1 = pos1.second;
