        std::set<std::pair<int,int>> visited;
        std::vector<std::pair<int,int>> stack{pos1};
        static const int dirs[4][2] = {{0,1},{0,-1},{1,0},{-1,0}};

        while (!stack.empty()) {
            auto current_pos = stack.back();
            stack.pop_back();
            if (current_pos == pos2) return true;
            if (visited.count(current_pos)) continue;
            visited.insert(current_pos);
            int x = current_pos.first, y = current_pos.second;
            for (auto& d : dirs) {
                int new_x = x + d[0], new_y = y + d[1];
                if (0 <= new_x && new_x < BOARD_SIZE[0] && 0 <= new_y && new_y < BOARD_SIZE[1]) {
