#include <xlnt/xlnt.hpp>
#include <fstream>
#include <optional>
#include <string>
#include <vector>
#include <algorithm>
#include <cctype>

class ExcelProcessor {
public:
    std::optional<std::vector<std::vector<std::string>>> read_excel(const std::string& file_name) {
        std::vector<std::vector<std::string>> data;
        try {
            xlnt::workbook workbook;
            std::ifstream ifs(file_name, std::ios::binary);
            if (!ifs) return std::nullopt;
            workbook.load(ifs); // or workbook.load(file_name)
            auto sheet = workbook.active_sheet();
            for (auto row : sheet.rows(false)) {
                std::vector<std::string> r;
                for (auto cell : row) {
                    r.push_back(cell.to_string());
                }
                data.push_back(r);
            }
            return data;
        } catch (...) {
            return std::nullopt;
        }
    }

    int write_excel(const std::vector<std::vector<std::string>>& data, const std::string& file_name) {
        try {
            xlnt::workbook workbook;
            auto sheet = workbook.active_sheet();
            for (const auto& row : data) {
                sheet.append(row);
            }
            workbook.save(file_name);
            return 1;
        } catch (...) {
            return 0;
        }
    }

    std::pair<int, std::string> process_excel_data(int N, const std::string& save_file_name) {
        auto data = read_excel(save_file_name);
        if (!data.has_value() || N >= (int)data.value()[0].size()) return {0, ""};
        std::vector<std::vector<std::string>> new_data;
        for (const auto& row : data.value()) {
            std::vector<std::string> new_row = row;
            const std::string& val = row[N];
            bool isDigit = !val.empty() && std::all_of(val.begin(), val.end(), ::isdigit);
            if (!isDigit) {
                std::string upper = val;
                std::transform(upper.begin(), upper.end(), upper.begin(), ::toupper);
                new_row.push_back(upper);
            } else {
                new_row.push_back(val);
            }
            new_data.push_back(new_row);
        }
        std::string base = save_file_name.substr(0, save_file_name.find('.'));
        std::string new_file_name = base + "_process.xlsx";
        int success = write_excel(new_data, new_file_name);
        return {success, new_file_name};
    }
};
```

