                    if (fixed[i] == '/') {
                        segments.push_back(unquote(seg, charset));
                        seg.clear();
                    } else {
                        seg.push_back(fixed[i]);
                    }
                }
                segments.push_back(unquote(seg, charset));
            }
        }
    }

