    static double dot(const std::vector<double>& a, const std::vector<double>& b) {
        double s = 0.0;
        const std::size_t n = std::min(a.size(), b.size());
        for (std::size_t i = 0; i < n; ++i) s += a[i] * b[i];
        return s;
