            for (std::size_t c = 0; c < mean.size(); ++c) {
                mean[c] += rows[r][c];
            }
        }
        const double n = static_cast<double>(rows.size());
        for (double& value : mean) {
            value /= n;
        }
        return mean;
    }
};
