static std::string python_dump(const nlohmann::json& j) {
    std::string s = j.dump();
    std::string out;
    out.reserve(s.size() + 8);
    bool in_str = false;
    bool esc = false;
    for (char c : s) {
        if (in_str) {
            out += c;
            if (esc) esc = false;
            else if (c == '\\') esc = true;
            else if (c == '"') in_str = false;
        } else {
            if (c == '"') { in_str = true; out += c; }
            else if (c == ',' ) { out += ", "; }
            else if (c == ':') { out += ": "; }
            else out += c;
        }
    }
    return out;
}
```

