```cpp
static void py_dump(const nlohmann::json& j, std::string& out) {
    using value_t = nlohmann::json::value_t;
    switch (j.type()) {
        case value_t::null: out += "null"; break;
        case value_t::boolean: out += j.get<bool>() ? "true" : "false"; break;
        case value_t::number_integer: out += j.dump(); break;
        case value_t::number_unsigned: out += j.dump(); break;
        case value_t::number_float: {
            double d = j.get<double>();
            if (std::isnan(d)) out += "NaN";
            else if (std::isinf(d)) out += d > 0 ? "Infinity" : "-Infinity";
            else out += j.dump();
            break;
        }
        case value_t::string: append_py_escaped(out, j.get_ref<const std::string&>()); break;
        case value_t::array: {
            out += '[';
            bool first = true;
            for (const auto& e : j) { if (!first) out += ", "; first = false; py_dump(e, out); }
            out += ']';
            break;
        }
        case value_t::object: {
            out += '{';
            bool first = true;
            for (auto it = j.begin(); it != j.end(); ++it) {
                if (!first) out += ", ";
                first = false;
                append_py_escaped(out, it.key());
                out += ": ";
                py_dump(it.value(), out);
            }
            out += '}';
            break;
        }
        default: throw nlohmann::json::type_error(...); // discarded — unreachable from parsed data
    }
}
