void JSONProcessor::append_py_string(std::string& out, const std::string& s) {
    out.push_back('"');
    std::size_t i = 0, n = s.size();
    while (i < n) {
        unsigned char c = static_cast<unsigned char>(s[i]);
        if (c == '"') { out += "\\\""; ++i; continue; }
        if (c == '\\') { out += "\\\\"; ++i; continue; }
        if (c == '\b') { out += "\\b"; ++i; continue; }
        if (c == '\f') { out += "\\f"; ++i; continue; }
        if (c == '\n') { out += "\\n"; ++i; continue; }
        if (c == '\r') { out += "\\r"; ++i; continue; }
        if (c == '\t') { out += "\\t"; ++i; continue; }
        if (c < 0x20) {
            char buf[8];
            std::snprintf(buf, sizeof buf, "\\u%04x", static_cast<unsigned>(c));
            out += buf;
            ++i;
            continue;
        }
        if (c < 0x80) { out.push_back(static_cast<char>(c)); ++i; continue; }
        // Decode UTF-8 sequence.
        unsigned cp = 0;
        std::size_t extra = 0;
        if ((c & 0xE0) == 0xC0) { cp = c & 0x1Fu; extra = 1; }
        else if ((c & 0xF0) == 0xE0) { cp = c & 0x0Fu; extra = 2; }
        else if ((c & 0xF8) == 0xF0) { cp = c & 0x07u; extra = 3; }
        else { cp = 0xFFFDu; extra = 0; }
        bool valid = true;
        for (std::size_t k = 0; k < extra; ++k) {
            unsigned char cc = (i + 1 + k < n) ? static_cast<unsigned char>(s[i + 1 + k]) : 0;
            if ((cc & 0xC0) != 0x80) { valid = false; break; }
            cp = (cp << 6) | (cc & 0x3Fu);
        }
        if (!valid) { cp = 0xFFFDu; extra = 0; i += 1; }
        else i += extra + 1;
        char buf[16];
        if (cp > 0xFFFF) {
            unsigned v = cp - 0x10000;
            std::snprintf(buf, sizeof buf, "\\u%04x\\u%04x",
                          0xD800 + (v >> 10), 0xDC00 + (v & 0x3FF));
        } else {
            std::snprintf(buf, sizeof buf, "\\u%04x", cp);
        }
        out += buf;
    }
    out.push_back('"');
}
