// JSON file processor: reading/writing JSON files and removing a specified key.
//
// Behavior mirrors the Python reference:
//   read_json    -> 0 if the file does not exist, -1 on any read/parse error,
//                   otherwise the parsed JSON value.
//   write_json   -> 1 on success, -1 on any error.
//   process_json -> 1 if the key was removed (even if the write-back later
//                   fails), 0 if the file is missing/unreadable or the key is
//                   absent; mirrors Python TypeError propagation for
//                   non-object JSON payloads.
// File output uses Python's json.dump defaults: insertion-ordered keys,
// ", " / ": " separators, ensure_ascii-style \uXXXX escaping, NaN/Infinity.

#include <cmath>
#include <cstdio>
#include <filesystem>
#include <fstream>
#include <stdexcept>
#include <string>
#include <variant>

#include <nlohmann/json.hpp>

using Json = nlohmann::ordered_json;  // preserves insertion (key) order like dict

class JSONProcessor {
public:
    // Returns 0 if the file does not exist, -1 if any error occurs while
    // reading/parsing, otherwise the parsed JSON data.
    std::variant<Json, int> read_json(const std::string& file_path) {
        if (!std::filesystem::exists(file_path)) {
            return 0;
        }
        try {
            std::ifstream file(file_path);
            Json data = Json::parse(file);
            return data;
        } catch (...) {
            return -1;
        }
    }

    // Writes `data` to `file_path`; returns 1 on success, -1 on any error.
    int write_json(const Json& data, const std::string& file_path) {
        try {
            std::ofstream file(file_path, std::ios::out | std::ios::trunc);
            if (!file) {
                return -1;
            }
            std::string out;
            py_dump(data, out);
            file.write(out.data(), static_cast<std::streamsize>(out.size()));
            file.flush();
            if (!file) {
                return -1;
            }
            return 1;
        } catch (...) {
            return -1;
        }
    }

    // Reads `file_path`, removes `remove_key` and writes the data back.
    int process_json(const std::string& file_path, const std::string& remove_key) {
        std::variant<Json, int> result = read_json(file_path);
        const Json* data = nullptr;
        if (const int* code = std::get_if<int>(&result)) {
            if (*code == 0 || *code == -1) {
                return 0;
            }
            return 0;  // unreachable: read_json only yields 0/-1 sentinels
        }
        data = &std::get<Json>(result);

        // Python: `if data == 0 or data == -1: return 0` (matches False/0/0.0/-1/-1.0)
        if (data->is_boolean()) {
            if (!data->get<bool>()) {
                return 0;  // False == 0 in Python
            }
            throw std::runtime_error("TypeError: argument of type 'bool' is not iterable");
        }
        if (data->is_null()) {
            throw std::runtime_error("TypeError: argument of type 'NoneType' is not iterable");
        }
        if (data->is_number()) {
            if (*data == Json(0) || *data == Json(-1)) {
                return 0;
            }
            throw std::runtime_error("TypeError: argument of type 'number' is not iterable");
        }
        if (data->is_string()) {
            const std::string& s = data->get_ref<const std::string&>();
            if (s.find(remove_key) != std::string::npos) {
                throw std::runtime_error("TypeError: 'str' object does not support item deletion");
            }
            return 0;
        }
        if (data->is_array()) {
            for (const Json& e : *data) {
                if (e == Json(remove_key)) {
                    throw std::runtime_error("TypeError: list indices must be integers or slices, not str");
                }
            }
            return 0;
        }

        // Object payload.
        Json obj = *data;
        if (!obj.contains(remove_key)) {
            return 0;
        }
        obj.erase(remove_key);
        write_json(obj, file_path);  // Python ignores the write result here
        return 1;
    }

private:
    // Appends `s` as a JSON string using Python json (ensure_ascii=True) escaping.
    static void append_py_string(std::string& out, const std::string& s) {
        out.push_back('"');
        std::size_t i = 0;
        const std::size_t n = s.size();
        while (i < n) {
            const unsigned char c = static_cast<unsigned char>(s[i]);
            if (c == '"')  { out += "\\\""; ++i; continue; }
            if (c == '\\') { out += "\\\\"; ++i; continue; }
            if (c == '\b') { out += "\\b";  ++i; continue; }
            if (c == '\f') { out += "\\f";  ++i; continue; }
            if (c == '\n') { out += "\\n";  ++i; continue; }
            if (c == '\r') { out += "\\r";  ++i; continue; }
            if (c == '\t') { out += "\\t";  ++i; continue; }
            if (c < 0x20) {
                char buf[8];
                std::snprintf(buf, sizeof buf, "\\u%04x", static_cast<unsigned>(c));
                out += buf;
                ++i;
                continue;
            }
            if (c < 0x80) {
                out.push_back(static_cast<char>(c));
                ++i;
                continue;
            }
            // Non-ASCII: decode the UTF-8 sequence, then emit \uXXXX (with surrogates).
            unsigned cp = 0;
            std::size_t extra = 0;
            if ((c & 0xE0u) == 0xC0u)      { cp = c & 0x1Fu; extra = 1; }
            else if ((c & 0xF0u) == 0xE0u) { cp = c & 0x0Fu; extra = 2; }
            else if ((c & 0xF8u) == 0xF0u) { cp = c & 0x07u; extra = 3; }
            else                           { cp = 0xFFFDu;   extra = 0; }
            bool valid = true;
            for (std::size_t k = 0; k < extra; ++k) {
                const unsigned char cc =
                    (i + 1 + k < n) ? static_cast<unsigned char>(s[i + 1 + k]) : 0u;
                if ((cc & 0xC0u) != 0x80u) { valid = false; break; }
                cp = (cp << 6) | (cc & 0x3Fu);
            }
            if (valid) {
                i += extra + 1;
            } else {
                cp = 0xFFFDu;
                i += 1;
            }
            char buf[16];
            if (cp > 0xFFFFu) {
                const unsigned v = cp - 0x10000u;
                std::snprintf(buf, sizeof buf, "\\u%04x\\u%04x",
                              0xD800u + (v >> 10), 0xDC00u + (v & 0x3FFu));
            } else {
                std::snprintf(buf, sizeof buf, "\\u%04x", cp);
            }
            out += buf;
        }
        out.push_back('"');
    }

    // Serializes like Python's json.dump defaults: ", "/": " separators,
    // insertion-ordered keys, NaN/Infinity literals.
    static void py_dump(const Json& j, std::string& out) {
        switch (j.type()) {
            case Json::value_t::null:
                out += "null";
                break;
            case Json::value_t::boolean:
                out += j.get<bool>() ? "true" : "false";
                break;
            case Json::value_t::number_integer:
            case Json::value_t::number_unsigned:
                out += j.dump();
                break;
            case Json::value_t::number_float: {
                const double d = j.get<double>();
                if (std::isnan(d)) {
                    out += "NaN";
                } else if (std::isinf(d)) {
                    out += (d > 0.0) ? "Infinity" : "-Infinity";
                } else {
                    out += j.dump();
                }
                break;
            }
            case Json::value_t::string:
                append_py_string(out, j.get_ref<const std::string&>());
                break;
            case Json::value_t::array: {
                out.push_back('[');
                bool first = true;
                for (const Json& e : j) {
                    if (!first) out += ", ";
                    first = false;
                    py_dump(e, out);
                }
                out.push_back(']');
                break;
            }
            case Json::value_t::object: {
                out.push_back('{');
                bool first = true;
                for (auto it = j.begin(); it != j.end(); ++it) {
                    if (!first) out += ", ";
                    first = false;
                    append_py_string(out, it.key());
                    out += ": ";
                    py_dump(it.value(), out);
                }
                out.push_back('}');
                break;
            }
            default:
                throw std::runtime_error("TypeError: value is not JSON serializable");
        }
    }
};
